// Généré par tools/art/gala_export.py : logo et sigle des LUCAS D'OR (arène CÉRÉMONIE)
const GALA_ART = {"logo": "data:image/png;base64,", "sigle": "data:image/png;base64,"};
const GALA_IMG = {};
function loadGalaArt() {
  return Promise.all(Object.keys(GALA_ART).map((k) => new Promise((ok) => {
    const im = new Image();
    im.onload = () => { GALA_IMG[k] = im; ok(); };
    im.onerror = () => ok();
    im.src = GALA_ART[k];
  })));
}
